-- Versioned reference snapshot; app and Edge Function ship verified copies of the same source.
CREATE TABLE IF NOT EXISTS public.service_contact_reference (
 organization_type text NOT NULL, intent_key text NOT NULL, service_area text NOT NULL,
 office_name text NOT NULL, phone text NOT NULL, duty text NOT NULL, keywords text[] NOT NULL DEFAULT '{}',
 source_file text NOT NULL, source_sheet text NOT NULL, source_row integer NOT NULL, source_sha256 text NOT NULL,
 updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (organization_type,intent_key,service_area)
);
CREATE TABLE IF NOT EXISTS public.service_intent_reference (
 intent_key text PRIMARY KEY, source_category text NOT NULL, business text NOT NULL, meaning text NOT NULL,
 examples text[] NOT NULL, source_file text NOT NULL, source_sheet text NOT NULL, source_row integer NOT NULL,
 source_sha256 text NOT NULL, updated_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.service_contact_reference ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.service_intent_reference ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.service_contact_reference, public.service_intent_reference FROM anon, authenticated;
GRANT SELECT ON public.service_contact_reference, public.service_intent_reference TO anon, authenticated;
GRANT ALL ON public.service_contact_reference, public.service_intent_reference TO service_role;
CREATE POLICY "Public reference contacts read only" ON public.service_contact_reference FOR SELECT TO anon,authenticated USING (true);
CREATE POLICY "Public reference intents read only" ON public.service_intent_reference FOR SELECT TO anon,authenticated USING (true);
